Given an expression with only '}' and '{'. The expression may not be balanced. Find minimum number of bracket reversals to make the expression balanced.Examples: Input: s = "}{{}}{{{"Output: 3Explanation: We need to reverse minimum 3 brackets to make "{{{}}{}}". Input: s = "{{"Output: 1Explanation: We need 1 reversal Input: s = "{{}{{{}{{}}{{"Output: -1Explanation: There's no way we can balance this sequence of braces as the length is odd.Try It YourselfTable of Content[Naive Approach] Recursive Bracket Reversal [Better Approach] Stack Based Bracket Reversal - O(n) time and O(n) space[Expected Approach] Two-Pointer Bracket Reversal - O(n) time and O(1) space[Naive Approach] Recursive Bracket Reversal This approach recursively checks all possible ways to reverse brackets to make the expression balanced. The algorithm explores two options for each bracket: keeping it as it is or reversing it. The goal is to find the minimum number of reversals needed to balance the string.Steps:Check if the string length is even: If it's odd, return -1 because a balanced string requires an even number of brackets.Recursive function: For each bracket, either keep it as is or reverse it, then check if the resulting string is balanced.Balance check: Traverse the string and maintain a count variable to track the balance of { and }. If at any point the count becomes negative, the string is unbalanced.Return the minimum number of reversals: If a balanced string is found, compare the number of reversals and store the minimum.
            C++

    #include <iostream>
using namespace std;

//Function to check that expression is balanced or not
bool isBalanced(string expr)
{
    // Initialising Variables
    bool flag = true;
    int count = 0;

    // Traversing the Expression
    for (int i = 0; i < expr.length(); i++) {

        if (expr[i] == '{') {
            count++;
        }
        else {
            // It is a closing bracket
            count--;
        }
        if (count < 0) {

            // This means there are more 
            // Closing brackets than opening ones
            flag = false;
            break;
        }
    }

    // If count is not zero, It means 
    // there are more opening brackets
    if (count != 0) {
        flag = false;
    }

    return flag;
}

void recur(string expr,int n,int ind,int change,int &ans){

    // When generated expression is balanced
    if(isBalanced(expr)){ans=min(ans,change);}

    // When we covered whole string
    if(ind==n){return;}

    // Keep bracket as it is
    recur(expr,n,ind+1,change,ans);

    // Reverse the bracket
    if(expr[ind]=='{'){expr[ind]='}';}
    else{expr[ind]='{';}
    recur(expr,n,ind+1,change+1,ans);
}


int countMinReversals(string expr)
{
    // Length of expression
    int n = expr.length();

    // To store answer
    int ans=INT_MAX;

    // When total number of brackets are odd
    if(n%2==1){
        return -1;
    }else{
        recur(expr,n,0,0,ans);
        return ans;
    }
}

int main()
{
    string expr = "}{{}}{{{";
    cout << countMinReversals(expr);
    return 0;
}


