            C++

    #include <iostream>
using namespace std;

int countMinReversals(string expr)
{
    int len = expr.length();

    // length of expression must be even to make, it balanced by using reversals.
    if (len % 2)
        return -1;

    stack<char> s;
    for (int i = 0; i < len; i++)
    {
        if (expr[i] == '}' && !s.empty())
        {
            if (s.top() == '{')
                s.pop();
            else
                s.push(expr[i]);
        }
        else
            s.push(expr[i]);
    }

    // Length of the reduced expression red_len = (m+n)
    int red_len = s.size();

    // count opening brackets at the end of stack
    int n = 0;
    while (!s.empty() && s.top() == '{')
    {
        s.pop();
        n++;
    }

    // return ceil(m/2) + ceil(n/2) which i actually equal to (m+n)/2 + n%2 when m+n is even.
    return (red_len / 2 + n % 2);
}

int main()
{
    string s = "}{{}}{{{";
    cout << countMinReversals(s);
    return 0;
}


